import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long total = nextLong();
        int m = (int) nextLong();
        long[][] a = new long[m + 1][];
        for (int i = 0; i < m; i++) a[i] = new long[] {nextLong(), nextLong()};
        Arrays.sort(a, 0, m, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        a[m] = new long[] {total + 1, total + 1};
        // A gap of length L splits into popcount(L) power-of-two chunks at minimum.
        long cursor = 1, answer = 0;
        for (long[] seg : a) {
            answer += Long.bitCount(seg[0] - cursor);
            cursor = seg[1] + 1;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"cmp"
	"fmt"
	"io"
	"math/bits"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	total := nextInt()
	m := int(nextInt())
	a := make([][2]int64, m)
	for i := range a {
		a[i] = [2]int64{nextInt(), nextInt()}
	}
	slices.SortFunc(a, func(x, y [2]int64) int {
		if x[0] != y[0] {
			return cmp.Compare(x[0], y[0])
		}
		return cmp.Compare(x[1], y[1])
	})
	a = append(a, [2]int64{total + 1, total + 1})
	// A gap of length L splits into popcount(L) power-of-two chunks at minimum.
	cursor, answer := int64(1), 0
	for _, seg := range a {
		answer += bits.OnesCount64(uint64(seg[0] - cursor))
		cursor = seg[1] + 1
	}
	fmt.Println(answer)
}
